      bg.setDisplaySize(400, 600);
    } else {
      this.add.rectangle(200, 300, 400, 600, 0x050510);
    }
    // 어두운 오버레이 (가독성 확보)
    this.add.rectangle(200, 300, 400, 600, 0x000000, 0.5);
