    this.ui(this.add.text(295, 117, '내 랭크', {
      fontSize: '12px', color: '#aaaaaa', stroke: '#000', strokeThickness: 2,
    }).setOrigin(0.5));
    this.rankBadgeImg = this.ui(
      this.add.image(248, 200, 'rank_alpha').setDisplaySize(74, 74).setAlpha(0),
